{
  "findings": [
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 Bucket CloudTrail Logging Disabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have server access logging enabled, which is a best practice for auditing access to the bucket itself."
    },
    {
      "check_id": "CKV_AWS_20",
      "title": "S3 Bucket Public Read Access Prohibited",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "The bucket lacks an explicit public access block configuration. Without this, the bucket could potentially be exposed publicly if misconfigured elsewhere or by default settings in some regions/accounts."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 Bucket Versioning Enabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "LOW",
      "explanation": "Versioning is not enabled on the bucket. For log storage, versioning helps protect against accidental deletion or overwriting of logs."
    },
    {
      "check_id": "CKV_AWS_27",
      "title": "S3 Bucket Encryption Enabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "Server-side encryption is not configured for the bucket. Data at rest should be encrypted using SSE-S3 or SSE-KMS to meet security compliance requirements."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket = "fleet-management-gps-tracking-system-cloudtrail-${random_string.bucket_suffix.result}"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "cloudtrail_logs" {
  bucket        = aws_s3_bucket.cloudtrail_logs.id
  target_bucket = aws_s3_bucket.cloudtrail_logs.id # In production, point to a separate secure logging bucket
  target_prefix = "log/"
}",
  "fix_summary": "Added server-side encryption (AES256), enabled versioning, applied strict public access blocks, and enabled server access logging to harden the S3 bucket configuration."
}
